WITH cleaned AS (SELECT *, COALESCE(revenue, 0) AS revenue_filled, units - revenue AS revenue_per_unit FROM store_sales WHERE sale_date > DATE '2023-08-04'), metrics AS (SELECT *, AVG(revenue_per_unit) OVER (PARTITION BY product_id, store_id) AS product_id_avg_revenue_per_unit, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue_filled DESC, id) AS seq_no FROM cleaned), with_dims AS (SELECT e.*, p.region FROM metrics e JOIN stores p ON e.store_id = p.id), with_dims_store_sales AS (SELECT src.*, b.opened_date FROM with_dims src LEFT JOIN stores b ON src.store_id = b.id), with_windows AS (SELECT id, store_id, product_id, sale_date, units, revenue, revenue_filled, revenue_per_unit, product_id_avg_revenue_per_unit, seq_no, region, opened_date, AVG(revenue) OVER (PARTITION BY product_id ORDER BY sale_date, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW) AS revenue_avg_3, NTILE(4) OVER (ORDER BY revenue_per_unit DESC, id) AS revenue_per_unit_bucket FROM with_dims_store_sales), enriched AS (SELECT *, AVG(revenue_filled) OVER (PARTITION BY product_id) AS product_id_avg_revenue_filled, SUM(revenue) OVER (ORDER BY opened_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_revenue, LAST_VALUE(revenue_filled, TRUE) OVER (PARTITION BY store_id ORDER BY revenue_filled, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_revenue_filled FROM with_windows) SELECT *, LAST_VALUE(cumulative_revenue) IGNORE NULLS OVER (PARTITION BY region ORDER BY units, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_cumulative_revenue, RANK() OVER (ORDER BY cumulative_revenue) AS cumulative_revenue_rank, SUM(units) OVER w_part AS cumulative_units FROM enriched WINDOW w_part AS (ORDER BY product_id_avg_revenue_per_unit, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
